// AWS Route53 - DNS Security Implementation
// Use AWS SDK or CloudFormation

// Method 1: AWS CLI - SPF Record
aws route53 change-resource-record-sets \
  --hosted-zone-id Z1234567890ABC \
  --change-batch '{
    "Changes": [{
      "Action": "UPSERT",
      "ResourceRecordSet": {
        "Name": "example.com",
        "Type": "TXT",
        "TTL": 300,
        "ResourceRecords": [{
          "Value": "\"v=spf1 include:_spf.google.com include:amazonses.com ~all\""
        }]
      }
    }]
  }'

// Method 2: AWS CLI - DMARC Record
aws route53 change-resource-record-sets \
  --hosted-zone-id Z1234567890ABC \
  --change-batch '{
    "Changes": [{
      "Action": "UPSERT",
      "ResourceRecordSet": {
        "Name": "_dmarc.example.com",
        "Type": "TXT",
        "TTL": 300,
        "ResourceRecords": [{
          "Value": "\"v=DMARC1; p=quarantine; rua=mailto:dmarc@example.com; ruf=mailto:dmarc@example.com; fo=1\""
        }]
      }
    }]
  }'

// Method 3: AWS CLI - CAA Record
aws route53 change-resource-record-sets \
  --hosted-zone-id Z1234567890ABC \
  --change-batch '{
    "Changes": [{
      "Action": "UPSERT",
      "ResourceRecordSet": {
        "Name": "example.com",
        "Type": "CAA",
        "TTL": 300,
        "ResourceRecords": [
          {"Value": "0 issue \"letsencrypt.org\""},
          {"Value": "0 issuewild \"letsencrypt.org\""},
          {"Value": "0 iodef \"mailto:security@example.com\""}
        ]
      }
    }]
  }'

// Method 4: CloudFormation - Complete DNS Security
Resources:
  SPFRecord:
    Type: AWS::Route53::RecordSet
    Properties:
      HostedZoneId: Z1234567890ABC
      Name: example.com
      Type: TXT
      TTL: 300
      ResourceRecords:
        - '"v=spf1 include:_spf.google.com include:amazonses.com ~all"'

  DMARCRecord:
    Type: AWS::Route53::RecordSet
    Properties:
      HostedZoneId: Z1234567890ABC
      Name: _dmarc.example.com
      Type: TXT
      TTL: 300
      ResourceRecords:
        - '"v=DMARC1; p=quarantine; rua=mailto:dmarc@example.com; pct=100; fo=1"'

  CAARecord:
    Type: AWS::Route53::RecordSet
    Properties:
      HostedZoneId: Z1234567890ABC
      Name: example.com
      Type: CAA
      TTL: 300
      ResourceRecords:
        - 0 issue "letsencrypt.org"
        - 0 issuewild "letsencrypt.org"
        - 0 iodef "mailto:security@example.com"

// Method 5: Enable DNSSEC (AWS Console)
// 1. Go to Route53 → Hosted zones
// 2. Select your hosted zone
// 3. Click "DNSSEC signing" tab
// 4. Click "Enable DNSSEC signing"
// 5. Route53 creates KSK (Key Signing Key)
// 6. Add DS record at your registrar:
//    - Key tag, algorithm, digest type, digest value
// 7. Wait for propagation (24-48 hours)
// 8. Verify with: dig +dnssec example.com

