// Python script to verify DNS security records
import dns.resolver
import requests
import json

def check_spf(domain):
    """Check SPF record"""
    try:
        answers = dns.resolver.resolve(domain, 'TXT')
        for rdata in answers:
            for txt_string in rdata.strings:
                if txt_string.decode().startswith('v=spf1'):
                    print(f"✅ SPF Record Found: {txt_string.decode()}")
                    return True
        print("❌ SPF Record Missing")
        return False
    except Exception as e:
        print(f"❌ SPF Check Failed: {e}")
        return False

def check_dmarc(domain):
    """Check DMARC record"""
    try:
        answers = dns.resolver.resolve(f'_dmarc.{domain}', 'TXT')
        for rdata in answers:
            for txt_string in rdata.strings:
                if txt_string.decode().startswith('v=DMARC1'):
                    print(f"✅ DMARC Record Found: {txt_string.decode()}")
                    return True
        print("❌ DMARC Record Missing")
        return False
    except Exception as e:
        print(f"❌ DMARC Check Failed: {e}")
        return False

def check_dkim(domain, selector='default'):
    """Check DKIM record"""
    try:
        dkim_domain = f"{selector}._domainkey.{domain}"
        answers = dns.resolver.resolve(dkim_domain, 'TXT')
        for rdata in answers:
            for txt_string in rdata.strings:
                if b'v=DKIM1' in txt_string:
                    print(f"✅ DKIM Record Found: {txt_string.decode()[:50]}...")
                    return True
        print("❌ DKIM Record Missing")
        return False
    except Exception as e:
        print(f"❌ DKIM Check Failed: {e}")
        return False

def check_caa(domain):
    """Check CAA record"""
    try:
        answers = dns.resolver.resolve(domain, 'CAA')
        print(f"✅ CAA Records Found:")
        for rdata in answers:
            print(f"   {rdata.flags} {rdata.tag.decode()} {rdata.value.decode()}")
        return True
    except dns.resolver.NoAnswer:
        print("❌ CAA Records Missing")
        return False
    except Exception as e:
        print(f"❌ CAA Check Failed: {e}")
        return False

def check_dnssec(domain):
    """Check DNSSEC"""
    try:
        # Use Google DNS API for DNSSEC validation
        url = f"https://dns.google/resolve?name={domain}&type=A&do=1"
        response = requests.get(url)
        data = response.json()

        if data.get('AD'):
            print(f"✅ DNSSEC Validated")
            return True
        else:
            print("❌ DNSSEC Not Validated")
            return False
    except Exception as e:
        print(f"❌ DNSSEC Check Failed: {e}")
        return False

# Run all checks
domain = "example.com"
print(f"\nDNS Security Check for {domain}\n")
print("="*50)

spf_ok = check_spf(domain)
dmarc_ok = check_dmarc(domain)
dkim_ok = check_dkim(domain)
caa_ok = check_caa(domain)
dnssec_ok = check_dnssec(domain)

print("\n" + "="*50)
if all([spf_ok, dmarc_ok, caa_ok, dnssec_ok]):
    print("\n✅ All DNS security checks passed!")
else:
    print("\n❌ Some DNS security checks failed. Review above.")

