// Node.js - Test DNS Security
const dns = require('dns').promises;
const axios = require('axios');

async function checkDNSSecurity(domain) {
  console.log(`\nDNS Security Check for ${domain}\n`);
  console.log('='.repeat(50));

  // Check SPF
  try {
    const records = await dns.resolveTxt(domain);
    const spf = records.find(r => r[0].startsWith('v=spf1'));
    if (spf) {
      console.log(`✅ SPF: ${spf[0]}`);
    } else {
      console.log('❌ SPF: Missing');
    }
  } catch (e) {
    console.log(`❌ SPF: Error - ${e.message}`);
  }

  // Check DMARC
  try {
    const records = await dns.resolveTxt(`_dmarc.${domain}`);
    const dmarc = records.find(r => r[0].startsWith('v=DMARC1'));
    if (dmarc) {
      console.log(`✅ DMARC: ${dmarc[0]}`);
    } else {
      console.log('❌ DMARC: Missing');
    }
  } catch (e) {
    console.log(`❌ DMARC: Error - ${e.message}`);
  }

  // Check CAA
  try {
    const records = await dns.resolveCaa(domain);
    if (records && records.length > 0) {
      console.log('✅ CAA: Found');
      records.forEach(r => console.log(`   ${r.issue || r.issuewild || r.iodef}`));
    } else {
      console.log('❌ CAA: Missing');
    }
  } catch (e) {
    console.log(`❌ CAA: Error - ${e.message}`);
  }

  // Check DNSSEC
  try {
    const response = await axios.get(
      `https://dns.google/resolve?name=${domain}&type=A&do=1`
    );
    if (response.data.AD) {
      console.log('✅ DNSSEC: Validated');
    } else {
      console.log('❌ DNSSEC: Not validated');
    }
  } catch (e) {
    console.log(`❌ DNSSEC: Error - ${e.message}`);
  }

  console.log('='.repeat(50));
}

checkDNSSecurity('example.com');
